        "loc-bldg7-1f": "Tòa nhà 7, Ban 1F",
        "loc-library": "Ban thư viện 1F",
        "loc-bldg8": "Đa chiều · Triển lãm",
        "map-meta-floor-label": "Sàn nhà:",
        "map-meta-items-label": "Các mặt hàng có sẵn:",
        "title-requirements": "Yêu cầu nộp đĩa than",
        "lead-requirements": "Các hạng mục thiết kế đang mở. Việc tạo ra các tác phẩm vật chất phải tuân theo các quy tắc an toàn về vật liệu và xử lý.",
        "req-cat-title": "Hạng mục thiết kế",
        "req-cat-text": "Không có hạn chế danh mục. Lĩnh vực đề xuất: thiết kế đồ họa, thiết kế sản phẩm, thiết kế dịch vụ, thời trang và thiết kế vấn đề xã hội.",
        "req-limit-title": "Giới hạn sử dụng đĩa than",
        "req-limit-text": "Công việc sử dụng đĩa than vật lý có thể sử dụng tới <strong>6</strong>. đĩa than không sử dụng không cần phải được trả lại.",
        "req-proc-title": "Kỹ thuật xử lý",
        "req-proc-text": "Bạn có thể cắt, uốn cong, nối hoặc kết hợp các đĩa than với các vật liệu khác, nhưng các quy tắc an toàn dưới đây là bắt buộc. Công việc làm nóng, chà nhám hoặc sử dụng dụng cụ điện chỉ được phép thực hiện trong không gian được phép với các biện pháp kiểm soát an toàn phù hợp.",
        "req-sub-title": "Tài liệu nộp",
        "req-sub-text": "Chỉ những công việc thể chất mới được chấp nhận. Đặt tác phẩm thực tế đã hoàn thành và mẫu đơn tham gia giấy in vào hộp sưu tập; hình ảnh, video tùy chọn và các tài liệu hỗ trợ khác có thể được gửi qua email.",
        "req-notice-text": "Bảo quản các tác phẩm vật lý đã hoàn thiện một cách an toàn và cố định các cạnh sắc hoặc các bộ phận không ổn định trước khi vận chuyển. Vui lòng xử lý rác thải đúng cách theo quy định xử lý do chính quyền địa phương quy định. Hãy đặt chúng vào hộp sưu tập trước MEDIA STUDIO trên tầng 2F của Tòa nhà 7 trước ngày 10 tháng 11.",
        "safety-kicker": "Đọc trước khi làm",
        "title-safety": "Xử lý an toàn",
        "lead-safety": "đĩa than bị loại bỏ thường được làm chủ yếu từ PVC. Cắt, làm nóng, chà nhám, khoan và liên kết có thể gây thương tích hoặc phơi nhiễm có hại, vì vậy hãy đánh giá phương pháp, vật liệu và không gian làm việc trước khi bắt đầu.",
        "pathway-safety-required-note": "Đường dẫn đã chọn của bạn xử lý các đĩa than vật lý. Đọc và làm theo tất cả các quy tắc dưới đây.",
        "safety-cut-title": "Cắt và các cạnh sắc nét",
        "safety-cut-text": "Các cạnh cắt, lưỡi dao và các mảnh vụn bay ra có thể gây thương tích cho tay hoặc mắt. Cố định vật liệu, sử dụng dụng cụ phù hợp với PVC và kính bảo vệ mắt, sau đó làm phẳng hoặc che các cạnh sắc.",
        "safety-heat-title": "Nhiệt, khói và bỏng",
        "safety-heat-text": "PVC quá nóng hoặc xuống cấp có thể giải phóng khói khó chịu. Không bao giờ sử dụng ngọn lửa trần hoặc nhiệt độ không kiểm soát được; chỉ sử dụng nhiệt độ thấp, ngắn hạn trong không gian làm việc được phép, có hệ thống thông gió hiệu quả hoặc thoát khí cục bộ và tránh các bề mặt nóng.",
